package main

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

var contractBlock = regexp.MustCompile("(?s)\n(`{3,})yaml\n(.*?)\n?`{3,}\n$")

// Every local $ref in a contract must resolve within that contract. (A "$ref" in example data,
// or one to another document, isn't expected to.)
func checkSelfContained(t *testing.T, name, page string) {
	t.Helper()
	m := contractBlock.FindStringSubmatch(page)
	if m == nil {
		t.Fatalf("%s has no YAML block:\n%s", name, page)
	}
	fragment, _, err := decodeSpec([]byte(m[2]))
	if err != nil {
		t.Fatalf("%s: %v\n%s", name, err, m[2])
	}
	r := &resolver{spec: fragment, warn: func(string, ...any) {}, warned: map[string]bool{}}
	var walk func(v any)
	walk = func(v any) {
		switch node := v.(type) {
		case map[string]any:
			if ref, ok := node["$ref"].(string); ok && strings.HasPrefix(ref, "#") {
				if _, ok := r.lookup(ref); !ok {
					t.Errorf("%s: %q does not resolve within the contract", name, ref)
				}
			}
			for _, child := range node {
				walk(child)
			}
		case []any:
			for _, child := range node {
				walk(child)
			}
		}
	}
	walk(fragment)
}

func TestContracts(t *testing.T) {
	spec, root, err := decodeSpec([]byte(petstore))
	if err != nil {
		t.Fatal(err)
	}
	files, warnings := contracts(root, spec, "https://example.com/openapi.yaml")
	if len(warnings) != 0 {
		t.Errorf("unexpected warnings: %v", warnings)
	}
	if len(files) != 9 {
		t.Errorf("got %d contract files, want 9", len(files))
	}
	for name, page := range files {
		checkSelfContained(t, name, page)
	}

	getPet := files["GetPet.md"]
	expect(t, getPet,
		"# GetPet\n\n<!-- Generated by openapi-reference",
		"`GET /pets/{petId}`: Get a pet\n",
		"```yaml\nopenapi: 3.0.3\npaths:\n  /pets/{petId}:\n    parameters:\n",
		"    get:\n      operationId: GetPet\n",
		"components:\n  parameters:\n    Fields:\n",
	)
	if strings.Contains(getPet, "PetFields") || strings.Contains(getPet, "delete:") {
		t.Errorf("GetPet's contract has something it doesn't reference:\n%s", getPet)
	}
	// Indirect references are followed: ReplacePet references PetFields, which is in schemas.
	// The YAML is the specification's own, styles and comments included.
	expect(t, files["ReplacePet.md"], "  schemas:\n    Name: {type: string}\n    PetFields:\n",
		"id: {type: string, maxLength: 8} # still read-only from the branch above")
}

func TestContractEdgeCases(t *testing.T) {
	doc := "openapi: 3.0.3\ninfo: {title: X, version: '1'}\n" +
		"paths:\n" +
		"  /pets:\n" +
		"    get:\n" +
		"      operationId: pets/list\n" + // not a safe file name
		"      summary: Code ```fenced``` in a summary\n" +
		"      description: \"Has ```` four backticks\"\n" +
		"      responses:\n" +
		"        '200': {description: OK, content: {application/json: {schema: {$ref: '#/components/schemas/Pet'}}}}\n" +
		"  /owners:\n" +
		"    get:\n" +
		"      operationId: ListOwners\n" +
		"      responses:\n" +
		"        '200': {description: OK, content: {application/json: {schema: &owner {type: object}}}}\n" +
		"    post:\n" +
		"      operationId: AddOwner\n" +
		"      requestBody: {content: {application/json: {schema: *owner}}}\n" +
		"components:\n  schemas:\n    Pet: {type: object, properties: {owner: {$ref: '#/components/schemas/Owner'}}}\n" +
		"    Owner: {type: object}\n"
	spec, root, err := decodeSpec([]byte(doc))
	if err != nil {
		t.Fatal(err)
	}
	files, _ := contracts(root, spec, "")
	list, ok := files["pets_list.md"]
	if !ok {
		t.Fatalf("no pets_list.md among %v", sortedKeys(files))
	}
	checkSelfContained(t, "pets_list.md", list)
	expect(t, list, "\n`````yaml\n", "    Owner: {type: object}\n", "    Pet: {") // fence longer than any run inside
	add := files["AddOwner.md"]
	if strings.Contains(add, "*owner") || strings.Contains(add, "&owner") {
		t.Errorf("an alias or anchor survived into the contract:\n%s", add)
	}
	expect(t, add, "schema: {type: object}")
}

func TestReferenceLinksContracts(t *testing.T) {
	spec, _, err := decodeSpec([]byte(petstore))
	if err != nil {
		t.Fatal(err)
	}
	out, _, err := render(spec, nil, "https://example.com/openapi.yaml", "https://example.com/ops/")
	if err != nil {
		t.Fatal(err)
	}
	expect(t, out, "- [`GetPet`](https://example.com/ops/GetPet.md) `get_pet` read `GET /pets/{petId}`\n")
	expectText(t, out, "Each operationId links to that operation's complete contract")
}

func TestWriteContractsRemovesOnlyStaleGeneratedFiles(t *testing.T) {
	dir := t.TempDir()
	write := func(name, content string) {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("Gone.md", "# Gone\n\n"+generatedComment)
	write("Notes.md", "# Someone's notes\n")
	if err := writeContracts(dir, map[string]string{"Kept.md": "# Kept\n\n" + generatedComment}); err != nil {
		t.Fatal(err)
	}
	for name, want := range map[string]bool{"Gone.md": false, "Notes.md": true, "Kept.md": true} {
		_, err := os.Stat(filepath.Join(dir, name))
		if exists := err == nil; exists != want {
			t.Errorf("%s exists = %v, want %v", name, exists, want)
		}
	}
}
